/*
 * Natural Language Grounded Search v3.2.0
 * Changes in v3.2.0:
 * - Runtime & Budget Hardening: Clamped all fetchWithTimeout calls to remainingBudgetMs(), propagated resources.signal (Live Voice Mode safe), added early empty-query validation, added GEMINI_PAID_API_KEY fallback, bounded multi-step callGemini continuation loop + max_output_tokens 400 retry + usage aggregation, added Decision 1 circuit breaker, hardened repairTruncatedJson, and tracked diagnostics.json_repairs & hydration_failures.
 * - Hydration & Workspace: Fixed single-read ArrayBuffer stream (eliminating "Body has already been read" on HTML-returning .pdf/.xlsx URLs) with streaming byte caps (14 MB PDF / 8 MB text) and SSRF guard for documentUrl; preserved <pre> code/generics/indentation, ASP.NET WebForms <form> content, and <a href> outbound links in extractStructuredHtml; fixed decodeHtmlEntities double-unescaping; hardened normalizeIsoDate & extractPublishedDateFromHtml; deduplicated loadSheetJS; staged per-sheet valid CSVs with unique domain+hash filenames and exposed staged_workspace_files[] on sources[].
 * - Search, RRF & Settings: Honored search_strategy (prefer_exa, prefer_brave, hybrid_cross_verify) across Hop-1 and Hop-2; fixed documentUrl-only mode without search keys; fixed single-domain include_domains capping & branch quota backfilling; decoupled Hop-2 freshness from Brave's 7-day 'pw' filter; fixed Exa 403/400 retries & 0-result failover; fixed discovered-doc RRF inflation; preserved hydrated text in mergeCandidatesByUrl; fixed makeFallbackRoutePlan code_extract regex hijack.
 * - SIFT, Citation Graph & Lattice: Pre-scanned full-text COI disclosures before SIFT; removed structural tier anchoring; enforced strict decision_1_calibrated mode and partial-SIFT preservation; decoupled credibility_label from query relevance (csc) and removed inverted promotional_bias_probability; added link-aware & Unicode-word-bounded citation graph with canonical cycle DFS pruning; fixed isTable shadowing bug and implemented fair round-robin 64-chunk semantic reranking across primary, adversarial, and Hop-2 sources.
 * - UCS, Verbatim & Entailment Integrity: Passed full Router + contextMetadata to UCS; replaced lossy alphanumeric verbatim normalizer with sign/operator-preserving check (min 4 chars, includes raw_code) and added claims[].quote_verified; skipped (instead of falsely deleting) unattached-PDF claims in Decision 1; enforced source-specific attribution verification ("citedList ONLY"), explicit skipped_cap_exceeded audits, Low-confidence preservation, and post-gate confidence_ceiling/completion_state recalibration.
 * - Hop-2 Atomicity & Output Contract: Removed opaque google_search/url_context from Hop-2 UCS; gave Hop-2 planner full Hop-1 context; fixed Hop-2 cross-engine RRF deduplication and atomic state commit; unified all output envelopes, enriched cited_sources[] with access_status & publishedDate, and sampled fallback_evidence_excerpts round-robin across all sources.
 */
async function natural_language_search(params, userSettings, resources) {
  const startTimeMs = Date.now();
  const HARD_BUDGET_MS = 78e3;
  const parentSignal = resources && resources.signal || null;

  function elapsedMs() {
    return Date.now() - startTimeMs;
  }
  function remainingBudgetMs() {
    return Math.max(0, HARD_BUDGET_MS - elapsedMs());
  }
  function isAborted() {
    return Boolean(parentSignal && parentSignal.aborted);
  }
  function clamp(num, min, max) {
    return Math.max(min, Math.min(max, num));
  }
  function unique(arr) {
    return Array.from(new Set((arr || []).filter(Boolean)));
  }
  function toArray(v) {
