  const actionOnError = uSettings.action_on_error || "return_diagnostic_json";

  const geminiDirectUrl = "https://generativelanguage.googleapis.com/v1beta/interactions";
  const decisionsDirectUrl = "https://generativelanguage.googleapis.com/v1beta/decisions";
