  function buildErrorEnvelope({
    completion_state = "failed",
    transport_state = "failed",
    failed_stage,
    api_error = null,
    error_diagnostic,
    need_class = null,
    breadth_mode = null,
    exactness_mode = null,
    search_mode = "single",
    branch_statuses = [],
