    citation_graph_warnings = { circular_chains: [], single_primary: null },
    hop2_verification = { executed: false, trigger_reasons: [], queries_run: [], added_sources_count: 0, ucs_reconciled: false }
  }) {
    const out = {
      completion_state,
      transport_state,
      failed_stage,
      api_error,
      error_diagnostic,
      need_class,
      breadth_mode,
      exactness_mode,
      retrieval_state: {
        search_mode,
        branch_statuses,
        missing_axes: unique(missing_axes),
        branch_errors,
        hydrated_documents_count: sources.filter((s) => s.is_hydrated).length,
        hop2_verification,
        pipeline_diagnostics: { ...diagnostics, elapsed_ms: elapsedMs() }
      },
      control_layer: {
        epistemic_tension: true,
        preferred_action,
        required_caveat: error_diagnostic,
        actionability_limit,
        confidence_ceiling: "Low",
        evidence_audit_notes: "",
        citation_graph_warnings
      },
      data_layer: {
        sources,
        artifacts: [],
        structured_items: [],
        claims: [],
        filtered_unverified_claims: [],
        missing_facets: unique([...missing_axes, error_diagnostic])
      }
    };
    if (fallback_evidence_excerpts) {
      out.data_layer.fallback_evidence_excerpts = fallback_evidence_excerpts;
    }
    return out;
  }

  if (!trimmedQuery && !trimmedDocumentUrl) {
    const emptyErr = "Missing required 'query' parameter (and no 'documentUrl' provided). Provide a specific search objective.";
    if (actionOnError === "throw_error_to_ui") throw new Error(emptyErr);
    return buildErrorEnvelope({
      failed_stage: "invalid_input",
      api_error: { has_error: true, error_type: "INVALID_INPUT", status_code: 400, message: emptyErr },
      error_diagnostic: emptyErr,
      missing_axes: ["empty_query"],
      preferred_action: "Provide a non-empty retrieval query or documentUrl and retry.",
      actionability_limit: "No query was provided to search."
    });
  }

  if (isAborted()) {
    const abortMsg = "Search execution was cancelled before starting.";
    return buildErrorEnvelope({
      completion_state: "degraded",
      transport_state: "degraded",
      failed_stage: "aborted",
      error_diagnostic: abortMsg,
      missing_axes: ["aborted"],
      preferred_action: "Execution was cancelled by the caller.",
      actionability_limit: "No external retrieval completed."
    });
  }

  async function fetchWithTimeout(url, options, timeoutMs) {
    if (isAborted()) {
      throw new Error("aborted_by_caller");
    }
    const budgetLeft = remainingBudgetMs();
    if (budgetLeft <= 1200) {
      throw new Error("execution_budget_exhausted");
    }
    const effectiveTimeout = Math.max(1500, Math.min(timeoutMs, budgetLeft - 1000));
    const controller = new AbortController();
    const onParentAbort = () => controller.abort();
    if (parentSignal && typeof parentSignal.addEventListener === "function") {
