      const hop2PlanSchema = {
        type: "object",
        properties: {
          verification_queries: {
            type: "array",
            items: { type: "string" },
            minItems: 1,
            maxItems: 2,
            description: "1 to 2 surgical primary-source queries to resolve missing facets, adjudicate contradictions, or locate original primary documents NOT already retrieved in Hop-1."
          }
        },
        required: ["verification_queries"]
      };
      const hop1QueriesRun = unique([routePlan.primary_query, routePlan.adversarial_query]);
      const hop1Domains = unique(sourceObjects.map((s) => s.domain));
      const paywalledDomains = unique(sourceObjects.filter((s) => s.access_status === "paywalled_preview").map((s) => s.domain));
      const hop2PlanPrompt = `<hop1_state>
<original_query>${sanitizeUntrustedXml(trimmedQuery)}</original_query>
<hop1_queries_already_run>${sanitizeUntrustedXml(JSON.stringify(hop1QueriesRun))}</hop1_queries_already_run>
<hop1_domains_fetched>${sanitizeUntrustedXml(JSON.stringify(hop1Domains))}</hop1_domains_fetched>
<paywalled_domains>${sanitizeUntrustedXml(JSON.stringify(paywalledDomains))}</paywalled_domains>
<rejected_claims>${sanitizeUntrustedXml(JSON.stringify((p1.filtered_unverified_claims || []).slice(0, 5)))}</rejected_claims>
<missing_facets>${sanitizeUntrustedXml(JSON.stringify(p1.missing_facets || []))}</missing_facets>
<epistemic_tension>${p1.epistemic_tension}</epistemic_tension>
<single_primary_warning>${sanitizeUntrustedXml(JSON.stringify(citationGraph.single_primary))}</single_primary_warning>
<audit_notes>${sanitizeUntrustedXml(truncate(p1.evidence_audit_notes || "", 2000))}</audit_notes>
</hop1_state>`;
      const hop2PlanCall = await callGemini({
        systemInstruction: `Formulate 1-2 surgical Hop-2 primary-source search queries targeting ONLY the unresolved gaps, disputed claims, or unverified primary sources in <hop1_state>. Do NOT repeat <hop1_queries_already_run>. Output JSON.`,
        inputBlocks: [{ type: "text", text: hop2PlanPrompt }],
        responseSchema: hop2PlanSchema,
        thinkingLevel: "low",
        maxOutputTokens: 8192,
        timeoutMs: 1e4
      });
      const hop2Plan = hop2PlanCall.ok ? parseStructuredJson(hop2PlanCall.text).parsed : null;
      const hop2Queries = toArray(hop2Plan?.verification_queries).slice(0, 2);
      if (hop2Queries.length > 0 && remainingBudgetMs() > 22e3 && !isAborted()) {
        hop2Telemetry.executed = true;
        hop2Telemetry.queries_run = hop2Queries;
        const hop2Engines = resolveEnginePlan(routePlan.need_class);
        const hop2SearchRuns = await Promise.all([
          runSearchBranch(hop2Engines.primary, "primary", hop2Queries[0], 5, true),
          hop2Queries[1] ? runSearchBranch(hop2Engines.adversarial, "adversarial", hop2Queries[1], 5, true) : Promise.resolve(null)
        ]);
        const hop1Urls = new Set(sourceObjects.map((s) => s.canonicalUrl || normalizeUrl(s.url)));
        const newCandidates = [];
        for (const run of hop2SearchRuns.filter(Boolean)) {
          branchStatuses.push({ branch: `hop2_${run.branch}`, engine: run.engine, status: run.status, via: run.via, error: run.error });
          if (run.status === "failed") {
            failedRuns.push({ branch: `hop2_${run.branch}`, engine: run.engine, error: run.error });
          }
          for (const r of run.results || []) {
            const nu = normalizeUrl(r.url);
            if (nu && !hop1Urls.has(nu)) {
              newCandidates.push({ ...r, branch: run.branch });
            }
          }
        }
        if (newCandidates.length > 0) {
          const hop2Map = mergeCandidatesByUrl(newCandidates, []);
          const hop2Picked = Array.from(hop2Map.values()).sort((a, b) => (b.rrf_score || 0) - (a.rrf_score || 0)).slice(0, 4);
          if (remainingBudgetMs() > 2e4 && !isAborted()) {
            const hop2ToHydrate = hop2Picked.filter((s) => {
              const pLower = safePathname(s.url).toLowerCase();
              if (/\.(pdf|xlsx|xls|csv)$/i.test(pLower)) return true;
              const status = detectAccessStatus(s);
              return (s.text || "").length < 2200 || status === "paywalled_preview" || status === "abstract_or_snippet";
            }).slice(0, 2);
            await Promise.all(hop2ToHydrate.map(async (s) => {
              const h = await fetchAndHydrateDocument(s.rawUrl || s.url);
              if (h.success) {
                let improved = false;
                if (h.is_native_pdf) {
                  s.is_native_pdf = true;
                  s.pdf_base64 = h.pdf_base64;
                  s.pdf_byte_length = h.pdf_byte_length;
                  s.mime_type = h.mime_type;
                  s.text = h.text;
                  improved = true;
                } else if ((h.text || "").length > (s.text || "").length) {
                  s.text = h.text;
                  improved = true;
                }
                if (improved) {
                  s.is_hydrated = true;
                  s.hydrated_type = h.type;
                  const stagedPaths = await stageDocumentToWorkspace(s.rawUrl || s.url, h, false);
                  if (stagedPaths.length > 0) {
                    s.staged_workspace_files = unique([...(s.staged_workspace_files || []), ...stagedPaths]);
                  }
                }
                if (Array.isArray(h.extractedLinks) && h.extractedLinks.length > 0) {
                  s.extractedLinks = unique([...(s.extractedLinks || []), ...h.extractedLinks]);
                }
                if (!s.publishedDate && (h.publishedDate || h.lastModified)) {
                  s.publishedDate = h.publishedDate || h.lastModified;
                }
                if (!s.lastModified && h.lastModified) s.lastModified = h.lastModified;
              }
            }));
          }
          const hop2Sources = attachInitialCredibility(hop2Picked, sourceObjects.length);
          await runFullSiftAudit(hop2Sources);
          const candidateSourceObjects = [...sourceObjects.map((s) => ({ ...s })), ...hop2Sources];
          const candidateCitationGraph = buildCitationGraph(candidateSourceObjects);
          attachCitationLinks(candidateSourceObjects, candidateCitationGraph);
          const candidateLattice = await buildEvidenceLattice(candidateSourceObjects, routePlan);
          if (remainingBudgetMs() > 18e3 && !isAborted()) {
            const hop2Ucs = await runUcsAndEntailmentPass(candidateSourceObjects, candidateLattice, candidateCitationGraph);
            if (hop2Ucs.ok && hop2Ucs.payload) {
              sourceObjects = candidateSourceObjects;
              citationGraph = candidateCitationGraph;
              evidenceLattice = candidateLattice;
              ucsRun = hop2Ucs;
              hop2Telemetry.ucs_reconciled = true;
              hop2Telemetry.added_sources_count = hop2Sources.length;
            } else {
              hop2Telemetry.abort_reason = hop2Ucs.error || "hop2_ucs_failed";
            }
          } else {
            hop2Telemetry.abort_reason = "insufficient_budget_for_hop2_ucs";
          }
        }
      }
    }
  }

  const branchMissingAxes = [];
  if (routePlan.search_mode === "dual") {
    if (!sourceObjects.some((s) => s.branch === "primary")) branchMissingAxes.push("supporting_evidence_under_sampled");
    if (!sourceObjects.some((s) => s.branch === "adversarial")) branchMissingAxes.push("counterevidence_under_sampled");
  }
  if (explicitDocumentFailed) {
    branchMissingAxes.push(`explicit_document_hydration_failed: ${trimmedDocumentUrl}`);
  }

  const cleanSourcesForOutput = sourceObjects.map(({
    id,
    title,
    url,
    domain,
    branch,
    role,
    access_status,
    search_engine,
    engines_matched,
    is_hydrated,
    hydrated_type,
    is_native_pdf,
    publishedDate,
    lastModified,
    retrievedAt,
    credibility_level,
    credibility_label,
    credibility_rationale,
    disclosure_note,
    staged_workspace_files,
    cites,
    cited_by,
    sift_audit
  }) => ({
    id,
    title,
    url,
    domain,
    branch,
    role,
    access_status: access_status || "abstract_or_snippet",
    search_engine,
    engines_matched: engines_matched || [search_engine],
    is_hydrated: Boolean(is_hydrated),
    hydrated_type: hydrated_type || null,
    is_native_pdf: Boolean(is_native_pdf),
    publishedDate: publishedDate || null,
    lastModified: lastModified || null,
    retrievedAt: retrievedAt || today,
    credibility_level,
    credibility_label,
    credibility_rationale,
    disclosure_note: disclosure_note || null,
    staged_workspace_files: staged_workspace_files || [],
    cites: cites || [],
    cited_by: cited_by || [],
    sift_audit
  }));

  function sampleFallbackExcerptsRoundRobin(lattice, maxTotal = 16) {
    const bySource = /* @__PURE__ */ new Map();
    for (const w of lattice) {
      if (!bySource.has(w.sourceId)) bySource.set(w.sourceId, []);
      bySource.get(w.sourceId).push(w);
    }
    const queues = Array.from(bySource.values());
    const picked = [];
    let round = 0;
    while (picked.length < maxTotal && queues.length > 0) {
      let added = false;
      for (const q of queues) {
        if (round < q.length && picked.length < maxTotal) {
          const w = q[round];
          picked.push({
            sourceId: w.sourceId,
            chunkIndex: w.idx,
            kind: w.kind,
            text: truncate(w.text, 2500)
          });
          added = true;
        }
      }
      if (!added) break;
      round += 1;
    }
    return picked;
  }

  if (!ucsRun.ok || !ucsRun.payload) {
    const failureNote = `UCS synthesis failed (${ucsRun.error || "unknown_synthesis_error"}). Returning retrieved sources and SIFT-audited evidence windows directly; inspect data_layer.fallback_evidence_excerpts before asserting claims.`;
    if (actionOnError === "throw_error_to_ui") throw new Error(failureNote);
    return buildErrorEnvelope({
      completion_state: "degraded",
      transport_state: transportState,
      failed_stage: "ucs_synthesis_failed",
      error_diagnostic: failureNote,
      need_class: routePlan.need_class,
      breadth_mode: routePlan.breadth_mode,
      exactness_mode: routePlan.exactness_mode,
      search_mode: routePlan.search_mode,
      branch_statuses: branchStatuses,
      branch_errors: failedRuns.map((r) => ({ branch: r.branch, engine: r.engine, error: r.error })),
      missing_axes: unique([...branchMissingAxes, "ucs_reconciliation_unavailable"]),
      preferred_action: "Synthesize directly from data_layer.fallback_evidence_excerpts and data_layer.sources with explicit caution.",
      actionability_limit: "Automated claim reconciliation and entailment gating did not complete.",
      sources: cleanSourcesForOutput,
      fallback_evidence_excerpts: sampleFallbackExcerptsRoundRobin(evidenceLattice, 16),
      citation_graph_warnings: {
        circular_chains: citationGraph.circular_chains,
        single_primary: citationGraph.single_primary
      },
      hop2_verification: hop2Telemetry
    });
  }

  const finalPayload = ucsRun.payload;
  const allMissingFacets = unique([...branchMissingAxes, ...toArray(finalPayload.missing_facets)]);
  const cleanSourceById = new Map(cleanSourcesForOutput.map((s) => [s.id, s]));

  function attachCitedSources(items) {
    return toArray(items).map((entry) => {
      const rawIds = unique(toArray(entry?.sourceIds));
      const validIds = rawIds.filter((sid) => cleanSourceById.has(sid));
      const invalidIds = rawIds.filter((sid) => !cleanSourceById.has(sid));
      const enriched = {
        ...entry,
        sourceIds: validIds,
        cited_sources: validIds.map((sid) => {
          const src = cleanSourceById.get(sid);
          return {
            id: src.id,
            title: src.title,
            url: src.url,
            domain: src.domain,
            publishedDate: src.publishedDate,
            access_status: src.access_status,
            credibility_label: src.credibility_label,
            sift_weight: src.sift_audit?.overall_epistemic_weight ?? null
          };
        })
      };
      if (invalidIds.length > 0) {
        enriched.invalid_source_ids_dropped = invalidIds;
      }
      return enriched;
    });
  }

  const dataLayerOut = {
    sources: cleanSourcesForOutput,
    artifacts: attachCitedSources(finalPayload.artifacts),
    structured_items: attachCitedSources(finalPayload.structured_items),
    claims: attachCitedSources(finalPayload.claims),
    filtered_unverified_claims: finalPayload.filtered_unverified_claims || [],
    missing_facets: allMissingFacets
  };
  if (detailMode === "RAW_TEXT") {
    dataLayerOut.raw_evidence_windows = evidenceLattice.map((w) => ({
      sourceId: w.sourceId,
      chunkIndex: w.idx,
      kind: w.kind,
      text: w.text
    }));
  }

  const allClaimsFilteredOut = (ucsRun.gateStats?.rejectedCount || 0) > 0 && dataLayerOut.claims.length === 0;
  const completionState = allClaimsFilteredOut || transportState === "degraded" || diagnostics.incomplete_generations > 0
    ? "degraded"
    : allMissingFacets.length > 0
      ? "partial"
      : "healthy";

  return {
    completion_state: completionState,
    transport_state: transportState,
    need_class: routePlan.need_class,
    breadth_mode: routePlan.breadth_mode,
    exactness_mode: routePlan.exactness_mode,
    retrieval_state: {
      search_mode: routePlan.search_mode,
      branch_statuses: branchStatuses,
      missing_axes: unique(branchMissingAxes),
      branch_errors: failedRuns.map((r) => ({ branch: r.branch, engine: r.engine, error: r.error })),
      hydrated_documents_count: cleanSourcesForOutput.filter((s) => s.is_hydrated).length,
      hop2_verification: hop2Telemetry,
      pipeline_diagnostics: { ...diagnostics, elapsed_ms: elapsedMs() }
    },
    control_layer: {
      epistemic_tension: Boolean(finalPayload.epistemic_tension),
      preferred_action: finalPayload.preferred_action,
      required_caveat: finalPayload.required_caveat,
      actionability_limit: finalPayload.actionability_limit,
      confidence_ceiling: allClaimsFilteredOut ? "Low" : finalPayload.confidence_ceiling,
      evidence_audit_notes: finalPayload.evidence_audit_notes || "",
      citation_graph_warnings: {
        circular_chains: citationGraph.circular_chains,
        single_primary: citationGraph.single_primary
      }
    },
    data_layer: dataLayerOut
  };
}
